@Mod.EventBusSubscriber(modid="touhou_little_maid")
public class MaidTrackEvent {
    @SubscribeEvent
    public static void onTrackingPlayer(PlayerEvent.StartTracking event) {
        Entity target = event.getTarget();
        Player player = event.getEntity();
        if (target instanceof EntityMaid) {
            Int2ObjectSortedMap<ItemStack> syncClientBauble;
            EntityMaid maid = (EntityMaid)target;
            if (maid.isYsmModel()) {
                SyncYsmMaidDataMessage message = new SyncYsmMaidDataMessage(maid.m_19879_(), maid.rouletteAnim, maid.rouletteAnimPlaying, maid.roamingVars);
                NetworkHandler.sendToClientPlayer(message, player);
            }
            if (!(syncClientBauble = maid.getMaidBauble().getSyncClientBauble(maid)).isEmpty()) {
                SyncBaubleMessage msg = SyncBaubleMessage.fullSync(maid.m_19879_(), syncClientBauble);
                NetworkHandler.sendToClientPlayer(msg, player);
            }
        }
    }
}

