package com.github.tartaricacid.touhoulittlemaid.geckolib3.core.keyframe.bone;

import com.github.tartaricacid.touhoulittlemaid.geckolib3.core.keyframe.bone.BoneKeyFrame;
import com.github.tartaricacid.touhoulittlemaid.geckolib3.core.keyframe.bone.EasingType;
import com.github.tartaricacid.touhoulittlemaid.geckolib3.core.keyframe.bone.RawBoneKeyFrame;
import it.unimi.dsi.fastutil.objects.ReferenceArrayList;
import java.util.List;

public class BoneKeyFrameProcessor {
    public static List<BoneKeyFrame> process(List<RawBoneKeyFrame> frames, boolean isRotation) {
        for (RawBoneKeyFrame frame : frames) {
            frame.init(isRotation);
        }
        Object[] list = new BoneKeyFrame[frames.size()];
        for (int i = 0; i < frames.size(); ++i) {
            RawBoneKeyFrame end = frames.get(i);
            EasingType easingType = end.easingType() == EasingType.CATMULLROM || i == 0 ? end.easingType() : frames.get(i - 1).easingType();
            list[i] = easingType.buildKeyFrame(frames, i);
        }
        return ReferenceArrayList.wrap((Object[])list);
    }
}

